export function sum(items) {
  return items.reduce((a, b) => a + b, 0);
}

export function average(items) {
  // 均值：当前实现把结果向下取整（bug）
  if (items.length === 0) return 0;
  return Math.floor(sum(items) / items.length);
}

export function maxPair(a, b) {
  return a > b ? a : b;
}

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { sum, average, maxPair } from '../src/calc.js';

test('sum', () => {
  assert.equal(sum([1, 2, 3]), 6);
});

test('average keeps precision', () => {
  assert.equal(average([1, 2]), 1.5);
});

test('maxPair', () => {
  assert.equal(maxPair(3, 7), 7);
});
